package cli

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
)

func TestZZProbeBadToken(t *testing.T) {
	clusterHost := "aws-us-east-2.entire.io"
	slug := "/gh/soph/go-git"
	checkURL := fmt.Sprintf("https://%s%s/info/refs?service=git-upload-pack", clusterHost, slug)
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	// 1. Mint a real token, then decode its exp claim to learn the TTL.
	token, err := auth.RepoScopedToken(ctx, "https://"+clusterHost, slug, "pull")
	if err != nil {
		t.Fatalf("mint: %v", err)
	}
	t.Logf("token (showing structure, not secret-sensitive in test): %d chars", len(token))
	// crude JWT exp peek
	logJWTExp(t, token)

	// 2. Hit the endpoint with a clearly-invalid/garbage token to see what
	//    status the data plane returns (what an *expired* token would look
	//    like to the probe's switch statement).
	for _, tok := range []string{"garbage-not-a-jwt", token + "tampered"} {
		req, _ := http.NewRequestWithContext(ctx, http.MethodGet, checkURL, nil)
		req.SetBasicAuth("entire-cli", tok)
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Logf("do ERR: %v", err)
			continue
		}
		raw, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		max := len(raw)
		if max > 200 {
			max = 200
		}
		label := tok
		if len(label) > 20 {
			label = label[:20] + "..."
		}
		t.Logf("token=%q -> status=%d www-authenticate=%q body=%q", label, resp.StatusCode, resp.Header.Get("WWW-Authenticate"), raw[:max])
	}
}

func logJWTExp(t *testing.T, token string) {
	t.Helper()
	parts := splitDots(token)
	if len(parts) < 2 {
		t.Logf("not a JWT (got %d parts)", len(parts))
		return
	}
	dec := base64URLDecode(parts[1])
	t.Logf("JWT claims: %s", dec)
}

func splitDots(s string) []string {
	var out []string
	cur := ""
	for _, c := range s {
		if c == '.' {
			out = append(out, cur)
			cur = ""
			continue
		}
		cur += string(c)
	}
	out = append(out, cur)
	return out
}

func base64URLDecode(s string) string {
	// pad
	for len(s)%4 != 0 {
		s += "="
	}
	b, err := decodeB64URL(s)
	if err != nil {
		return fmt.Sprintf("<decode err: %v>", err)
	}
	return string(b)
}

