package cli

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"testing"
	"time"

	"github.com/go-git/go-git/v6/plumbing/protocol/packp"

	"github.com/entireio/cli/cmd/entire/cli/auth"
)

func TestZZProbeRepeat(t *testing.T) {
	clusterHost := "aws-us-east-2.entire.io"
	slug := "/gh/soph/go-git"
	checkURL := fmt.Sprintf("https://%s%s/info/refs?service=git-upload-pack", clusterHost, slug)

	for i := 0; i < 8; i++ {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		token, err := auth.RepoScopedToken(ctx, "https://"+clusterHost, slug, "pull")
		if err != nil {
			t.Logf("attempt %d: MINT ERR: %v", i, err)
			cancel()
			time.Sleep(500 * time.Millisecond)
			continue
		}
		req, _ := http.NewRequestWithContext(ctx, http.MethodGet, checkURL, nil)
		req.SetBasicAuth("entire-cli", token)
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Logf("attempt %d: HTTP ERR: %v", i, err)
			cancel()
			continue
		}
		raw, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		ready, decErr := decodeReady(raw)
		t.Logf("attempt %d: mint OK status=%d bodylen=%d ready=%v decErr=%v", i, resp.StatusCode, len(raw), ready, decErr)
		cancel()
		time.Sleep(300 * time.Millisecond)
	}
}

func decodeReady(raw []byte) (bool, error) {
	r := &sliceReader{b: raw}
	var sr packp.SmartReply
	if err := sr.Decode(r); err != nil {
		return false, fmt.Errorf("smartreply: %w", err)
	}
	var adv packp.AdvRefs
	if err := adv.Decode(r); err != nil {
		return false, fmt.Errorf("advrefs: %w", err)
	}
	if _, err := adv.ResolvedHead(); err != nil {
		return false, fmt.Errorf("resolvedhead: %w", err)
	}
	return true, nil
}

type sliceReader struct {
	b []byte
	i int
}

func (r *sliceReader) Read(p []byte) (int, error) {
	if r.i >= len(r.b) {
		return 0, io.EOF
	}
	n := copy(p, r.b[r.i:])
	r.i += n
	return n, nil
}

