// checkRedirect is the http.Client CheckRedirect hook. It caps
// redirect chains and enforces an explicit same-cluster policy for the
// Authorization header: in-cluster hops re-carry it (Go's default
// strips on cross-host redirect, which would otherwise drop the
// credential when info/refs 307s from the entry domain to a hosting
// replica), out-of-cluster hops strip it.
//
// The explicit strip matters: Go's default shouldCopyHeaderOnRedirect
// keys on hostname only, so same-host-different-port hops (common with
// local test servers, and possible with a misconfigured LB) would
// otherwise carry Authorization through. We'd rather drop the header
// than leak it.
func (p *Proxy) checkRedirect(req *http.Request, via []*http.Request) error {
	if len(via) >= 10 {
		return errors.New("stopped after 10 redirects")
	}
	if len(via) == 0 {
		return nil
	}
	if p.clusterHost != "" && !discovery.HostInCluster(req.URL.Hostname(), p.clusterHost) {
		debuglog.Printf("redirect to %s is out-of-cluster (cluster=%s); stripping Authorization", req.URL.Host, p.clusterHost)
		req.Header.Del("Authorization")
		return nil
	}
	if auth := via[0].Header.Get("Authorization"); auth != "" {
		debuglog.Printf("redirect to %s is in-cluster (cluster=%s); preserving Authorization", req.URL.Host, p.clusterHost)
		req.Header.Set("Authorization", auth) //nolint:gosec // intentional: preserve auth for in-cluster hops (out-of-cluster is stripped above)
	}
	return nil
}

// hostInCluster reports whether host is the cluster's entry domain or a
// subdomain of it. With no clusterHost configured (un-pinned callers and
// some tests) it returns true — there is no trust domain to enforce, which
// matches checkRedirect's behaviour.
func (p *Proxy) hostInCluster(host string) bool {
	if p.clusterHost == "" {
		return true
	}
	return discovery.HostInCluster(host, p.clusterHost)
}

// replicaInCluster reports whether a replica base URL is safe to dial with
// the repo-scoped token attached: it must parse and resolve to a host
// inside the cluster trust domain. Replica sets arrive from

input.old_string:
	// The cluster front door 307-redirects info/refs to the node actually
	// holding the mirror (e.g. bishop.<cluster-host>), embedding a pull
	// token in the redirect's userinfo. git follows these to clone, so the
	// probe must too — refusing them (the old http.ErrUseLastResponse) made
	// mirrorAdvertisesHead see the 307 as "not 200, not ready" and spin the
	// cloning-dots forever even after the clone had landed. checkProbeRedirect
	// keeps following bounded and confined to the cluster host so the
	// userinfo token can't leak to an unrelated host.
	CheckRedirect: checkProbeRedirect,
}

// maxProbeRedirects bounds redirect-following during the clone probe.
// One front-door→node hop is expected; the cap is headroom against a
// misconfigured loop, not snugness.
const maxProbeRedirects = 5

// checkProbeRedirect confines the clone probe's redirect-following to the
// original cluster host or a subdomain of it, over https. The 307 the cluster
// front door issues carries the pull token in the Location userinfo (git uses
// it to reach the backing node); following that to an unrelated host would
// hand the token to whoever the redirect named. A login-page redirect can't
// produce a false "ready" either way — mirrorAdvertisesHead only reports ready
// when the body decodes as a git advertisement with a resolvable HEAD — so the
// host confinement here is purely about not leaking the token.
func checkProbeRedirect(req *http.Request, via []*http.Request) error {
	if len(via) >= maxProbeRedirects {
		return fmt.Errorf("stopped after %d redirects", maxProbeRedirects)
	}
	if req.URL.Scheme != "https" {
		return fmt.Errorf("refusing non-https redirect to %s", req.URL.Redacted())
	}
	orig := via[0].URL.Hostname()
	host := req.URL.Hostname()
	if host != orig && !strings.HasSuffix(host, "."+orig) {
		return fmt.Errorf("refusing cross-host redirect to %s", req.URL.Redacted())
	}
	return nil
}

